/usr/bin/bash -lc "python - <<'PY'
import functools
import inspect
from boltons.funcutils import FunctionBuilder, wraps

class Example:
    def method(self, /, value=1):
        return value

for obj in [Example.method, Example().method, functools.partial(Example.method, Example())]:
    try:
        print(type(obj).__name__, inspect.getfullargspec(obj), inspect.signature(obj, follow_wrapped=False))
        fb = FunctionBuilder.from_func(obj)
        print('  fb:', fb.args, fb.posonlyargs, fb.get_sig_str(), fb.get_invocation_str())
    except Exception as exc:
        print('  error:', type(exc).__name__, exc)
PY
python -m pytest -q --ignore=tests/test_socketutils.py"

